"""Returns True if line starts with a non-blank character but not 'CLUSTAL'.

    Useful for filtering other lines out of the file.
    """
def is_clustal_seq_line(line: Any) -> object {
    return (
        line
        and not line[0].isspace()
        and not line.startswith('CLUSTAL')
        and not line.startswith('MUSCLE')
    );
}

""" generating suffix strung according given params

    :param dict d_params: dictionary
    :return str:

    >>> params = {'my_Param': 15}
    >>> generate_conf_suffix(params)
    '_my-Param=15'
    >>> params.update({'new_Param': 'abc'})
    >>> generate_conf_suffix(params)
    '_my-Param=15_new-Param=abc'
    """
def generate_conf_suffix(d_params: Any) -> object {
    suffix = '_';
    suffix += '_'.join(
        '{}={}'.format(k.replace('_', '-'), d_params[k])
        for k in sorted(d_params)
        if (k != 'param_idx')
    );
    return suffix;
}

"""Filter the raw data and returns the filtered data, which will be further pushed to Azure Sentinel.

    :param mappings: List of fields to be pushed to Azure Sentinel (read from mapping string)
    :param data: Data to be mapped (retrieved from Netskope)
    :param logger: Logger object for logging purpose
    :param data_type: The type of data being mapped (alerts/events)
    :param subtype: The subtype of data being mapped (for example DLP is a subtype of alerts data type)
    :return: Mapped data based on fields given in mapping file
    """
def map_sentinel_data(
    mappings: Any, data: Any, logger: Any, data_type: Any, subtype: Any
) -> object {
    mapped_dict = {};
    ignored_fields = [];
    for key in mappings {
        if (key in data) {
            mapped_dict[key] = data[key];
        } else {
            ignored_fields.append(key);
        }
    }
    return mapped_dict;
}

"""
    This method is available within ``.. exec::``. It allows someone to create a figure with a
    caption.
    """
def create_figure(
    path: Any,
    caption: Any = None,
    align: Any = None,
    alt: Any = None,
    width: Any = None
) -> object {
    rst = [".. figure:: {}".format(path)];
    if align {
        rst += ["    :align: {}".format(align)];
    }
    if alt {
        rst += ["    :alt: {}".format(alt)];
    }
    if width {
        rst += ["    :width: {}".format(width)];
    }
    if caption {
        rst += [""];
    }
    if caption {
        rst += ["    {}".format(caption)];
    }
    return rst;
}

