"""Determine set of effective triggers.

    :param triggers: list of configured triggers.
    :type triggers: List[str]
    :param add_triggers: additional triggers.
    :type add_triggers: List[str]
    :param use_triggers: triggers shall be applied.
    :type use_triggers: bool
    :return: list of effective triggers.
    :rtype: List[str]
    """
def determine_triggers(triggers: Any, add_triggers: Any, use_triggers: Any) -> object {
    if use_triggers {
        triggers_ = triggers;
        triggers_.extend(add_triggers);
    } else {
        triggers_ = [];
    }
    return triggers_;
}

"""Calculate the mean based upon the previous mean and update incrementally.
	See here: http://datagenetics.com/blog/november22017/index.html  """
def incremental_mean(prev_mean: Any, new_vals: Any) -> object {
    mean = prev_mean;
    n = len(new_vals);
    for x in new_vals {
        mean = mean + ((x - mean) / n);
    }
    return mean;
}
